function transferJdk7(head) {
  let out = null
  let cur = head
  while (cur) {
    out = { key: cur.key, next: out }
    cur = cur.next
  }
  return out
}

function hasCycle(head) {
  let slow = head
  let fast = head
  while (fast && fast.next) {
    slow = slow.next
    fast = fast.next.next
    if (slow === fast) return true
  }
  return false
}

function findCycleStart(head) {
  let slow = head
  let fast = head
  while (fast && fast.next) {
    slow = slow.next
    fast = fast.next.next
    if (slow === fast) {
      let p = head
      while (p !== slow) {
        p = p.next
        slow = slow.next
      }
      return p
    }
  }
  return null
}

stages.test:
{
  check('JDK7 头插法会把链表顺序反转', () => {
    const a = { key: 3, next: null }
    const b = { key: 7, next: a }
    const c = { key: 11, next: b }
    const out = transferJdk7(c)
    same(out.key, 3, '原尾变成新头')
    same(out.next.key, 7)
    same(out.next.next.key, 11)
  })
  check('正常链表没有环', () => {
    same(hasCycle({ key: 1, next: { key: 2, next: null } }), false)
    same(hasCycle(null), false)
    same(hasCycle({ key: 1, next: null }), false)
  })
  check('并发下互相指向形成环（扩容死循环现场）', () => {
    const x = { key: 1 }
    const y = { key: 2 }
    x.next = y
    y.next = x
    same(hasCycle(x), true)
  })
  check('用快慢指针找出环的入口', () => {
    const a = { key: 1 }
    const b = { key: 2 }
    const c = { key: 3 }
    a.next = b
    b.next = c
    c.next = b
    same(findCycleStart(a).key, 2)
    same(findCycleStart({ key: 9, next: null }), null)
  })
}

